/**
 * @agrorende/motion: original Lottie animations for the landing site, the admin web app and
 * the mobile app. The JSON files in `lottie/` are generated by `pnpm build:lottie` from the
 * builders in `src/animations/`; never edit them by hand.
 */
import type { LottieJson } from "./lottie/types.js";
import type { AnimationId } from "./meta.js";
import welcomeJson from "../lottie/welcome.json";
import reportOfflineJson from "../lottie/report-offline.json";
import flowLoopJson from "../lottie/flow-loop.json";
import machineCostJson from "../lottie/machine-cost.json";
import officeLiveJson from "../lottie/office-live.json";
import inviteTeamJson from "../lottie/invite-team.json";
import firstMachineJson from "../lottie/first-machine.json";
import firstWorkOrderJson from "../lottie/first-work-order.json";
import signatureJson from "../lottie/signature.json";
import successJson from "../lottie/success.json";
import emptyJson from "../lottie/empty.json";
import savedOnPhoneJson from "../lottie/saved-on-phone.json";
import rentalHandoverJson from "../lottie/rental-handover.json";
import loadingJson from "../lottie/loading.json";

export { ANIMATION_IDS, motionMeta, type AnimationId, type MotionMeta } from "./meta.js";
export type { LottieJson } from "./lottie/types.js";

/**
 * Every animation, imported eagerly. Metro needs static requires, so the mobile app uses this
 * record; web surfaces should prefer `loadAnimation` to keep the JSON out of the main bundle.
 */
export const animations: Record<AnimationId, LottieJson> = {
  welcome: welcomeJson,
  "report-offline": reportOfflineJson,
  "flow-loop": flowLoopJson,
  "machine-cost": machineCostJson,
  "office-live": officeLiveJson,
  "invite-team": inviteTeamJson,
  "first-machine": firstMachineJson,
  "first-work-order": firstWorkOrderJson,
  signature: signatureJson,
  success: successJson,
  empty: emptyJson,
  "saved-on-phone": savedOnPhoneJson,
  "rental-handover": rentalHandoverJson,
  loading: loadingJson,
};

/** Loads one animation lazily. The static switch lets Next.js (Turbopack/webpack) and Metro split each file. */
export async function loadAnimation(id: AnimationId): Promise<LottieJson> {
  switch (id) {
    case "welcome":
      return (await import("../lottie/welcome.json")).default;
    case "report-offline":
      return (await import("../lottie/report-offline.json")).default;
    case "flow-loop":
      return (await import("../lottie/flow-loop.json")).default;
    case "machine-cost":
      return (await import("../lottie/machine-cost.json")).default;
    case "office-live":
      return (await import("../lottie/office-live.json")).default;
    case "invite-team":
      return (await import("../lottie/invite-team.json")).default;
    case "first-machine":
      return (await import("../lottie/first-machine.json")).default;
    case "first-work-order":
      return (await import("../lottie/first-work-order.json")).default;
    case "signature":
      return (await import("../lottie/signature.json")).default;
    case "success":
      return (await import("../lottie/success.json")).default;
    case "empty":
      return (await import("../lottie/empty.json")).default;
    case "saved-on-phone":
      return (await import("../lottie/saved-on-phone.json")).default;
    case "rental-handover":
      return (await import("../lottie/rental-handover.json")).default;
    case "loading":
      return (await import("../lottie/loading.json")).default;
  }
}
